-- ----------------------------------------------------------------------------
-- Subscription Service menu + terms dummy/reference seed
-- Target: MySQL 8.4.x
-- Prerequisite: schema.sql and plans seed (간편식/가정식/든든식) must already be applied.
--
-- IMPORTANT
-- 1) menus: 3 plans x 31 sequences = 93 rows, following the ERD rule.
-- 2) nutrition/allergen/ingredient values below are fictional DEVELOPMENT DUMMY DATA.
--    They are plausible UI/test values, NOT laboratory-tested or legally verified food-label information.
-- 3) terms v1 follows POL-TERMS-001. Unconfirmed liability/indemnity clauses are intentionally not added.
-- 4) Run menu seed before creating business orders that reference menus. Menus are fixed master data in the MVP.
--
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
START TRANSACTION;

-- -----------------------------------------------------------------------------
-- Resolve plan IDs by stable plan name instead of hard-coding internal AUTO_INCREMENT IDs.
-- -----------------------------------------------------------------------------
SET @plan_simple = (SELECT id FROM plans WHERE name = '간편식' LIMIT 1);
SET @plan_home   = (SELECT id FROM plans WHERE name = '가정식' LIMIT 1);
SET @plan_hearty = (SELECT id FROM plans WHERE name = '든든식' LIMIT 1);

-- If any plan is missing, menus.plan_id NOT NULL will make the INSERT fail.
SELECT
    @plan_simple AS simple_plan_id,
    @plan_home AS home_plan_id,
    @plan_hearty AS hearty_plan_id;

-- -----------------------------------------------------------------------------
-- menus: 93 rows
-- menu_sequence 1~31 maps to DAY(delivery_date).
-- -----------------------------------------------------------------------------
