INSERT INTO terms (
    terms_type,
    version_number,
    title,
    content,
    is_required,
    is_current
) VALUES
         (
             'NON_FACE_TO_FACE_STORAGE',
             1,
             '비대면 보관 약관',
             '챱챱은 고객이 지정한 배송지와 배달 요청사항에 따라 구독 상품을 배송합니다.

         1. 고객이 배송 시 상품을 직접 수령하지 못하는 경우, 고객이 배송지에 설정한 배달 방식과 요청사항에 따라 상품이 문 앞 또는 고객이 지정한 장소에 보관될 수 있습니다.

         2. 고객은 배송지마다 다음 배달 방식 중 하나를 선택합니다.
            - 직접 받을게요
            - 문 앞 배송
            - 기타

            `기타`를 선택한 경우 고객이 입력한 요청사항을 해당 배송지의 배달 요청사항으로 사용합니다.

         3. 구독 주문은 주문이 생성될 당시 확정된 배송지와 배달 요청사항을 기준으로 처리됩니다.

         4. 본 약관은 첫 구독 신청을 완료하고 첫 결제를 진행하기 전에 반드시 동의해야 하는 필수 약관입니다. 본 약관에 동의하지 않은 경우 첫 구독 신청 및 결제를 진행할 수 없습니다.

         5. 고객의 동의 사실은 동의한 약관의 버전 및 동의 시각과 함께 기록됩니다. 동일한 약관 버전에 다시 동의하더라도 기존 동의 기록이 유지됩니다.

         6. 구독을 통해 생성되는 주문은 해당 고객이 동의한 비대면 보관 약관 기록을 기준으로 생성됩니다.

         본인은 위 내용을 확인하였으며, 배송 과정에서 직접 수령하지 못하는 경우 선택한 배달 방식 및 요청사항에 따라 상품이 문 앞 또는 지정한 장소에 보관될 수 있음에 동의합니다.',
             TRUE,
             TRUE
         ),
         (
             'SUBSCRIPTION_SERVICE_TERMS',
             1,
             '구독 서비스 이용 및 정기결제 약관',
             '본 약관은 챱챱 구독 서비스의 이용, 정기결제, 설정 변경, 배송 및 환불 처리에 적용됩니다.

         1. 구독은 첫 결제가 완료된 날을 기준으로 28일 단위 이용 기간으로 운영되며, 고객이 해지하지 않으면 다음 이용 기간에 자동 갱신되고 등록된 자동결제수단으로 정기결제가 진행됩니다.

         2. 결제금액은 선택한 플랜, 배송 요일별 수량, 배송 조건, 할인 및 적용 가능한 환불·추가 결제 금액을 기준으로 계산합니다. 첫 결제와 정기결제의 결제 시점 및 금액은 결제 전 화면 또는 안내를 통해 확인할 수 있습니다.

         3. 고객은 서비스가 정한 기준에 따라 구독을 해지하거나, 이용 시작 전 첫 구독을 취소하거나, 다음 이용 기간부터 적용되는 해지를 신청할 수 있습니다. 각 처리의 적용 시점과 환불 여부는 신청 시점 및 이미 제공된 서비스 범위를 기준으로 안내합니다.

         4. 플랜, 수량 또는 배송 조건을 변경하여 금액 차이가 발생하면 최종 확인 화면에서 변경 후 금액, 추가 결제 또는 환불 금액과 적용일을 안내합니다. 고객이 확인한 변경만 처리하며, 증액은 추가 결제 성공 후, 감액은 환불 처리 기준에 따라 반영합니다.

         5. 일요일과 공휴일은 배송하지 않으며, 해당 일정은 이용 기간 계산과 배송 일정에 반영됩니다. 서비스의 귀책으로 배송이 실패한 경우에는 확인된 사유와 서비스 정책에 따라 환불 또는 후속 조치를 진행합니다.

         6. 정기결제가 실패하면 서비스는 등록된 수단으로 재시도하거나 고객에게 실패 사실과 필요한 조치를 안내할 수 있습니다. 최종 결제 실패 시에는 다음 이용 기간의 이용·배송이 시작되지 않거나 구독 상태가 변경될 수 있으며, 그 결과를 고객에게 안내합니다.

         7. 본 약관은 전자상거래 등 관련 법령에 따른 고객의 청약철회 및 환불 권리를 제한하지 않습니다. 법령상 예외 또는 별도 절차가 필요한 경우에는 관련 법령과 고객에게 고지한 기준을 따릅니다.

         본인은 위 구독 서비스 이용 및 정기결제 기준을 확인하고 동의합니다.',
             TRUE,
             TRUE
         )
    AS new
ON DUPLICATE KEY UPDATE
                     terms_type = new.terms_type;

COMMIT;

-- -----------------------------------------------------------------------------
-- Verification
-- Expected: 간편식 31 / 가정식 31 / 든든식 31 / total 93
-- -----------------------------------------------------------------------------
SELECT
    p.name AS plan_name,
    COUNT(*) AS menu_count,
    MIN(m.menu_sequence) AS min_sequence,
    MAX(m.menu_sequence) AS max_sequence
FROM menus m
         JOIN plans p ON p.id = m.plan_id
WHERE p.name IN ('간편식', '가정식', '든든식')
GROUP BY p.id, p.name
ORDER BY FIELD(p.name, '간편식', '가정식', '든든식');

SELECT COUNT(*) AS total_menu_count
FROM menus m
         JOIN plans p ON p.id = m.plan_id
WHERE p.name IN ('간편식', '가정식', '든든식');

SELECT
    terms_type,
    version_number,
    title,
    is_required,
    is_current
FROM terms
WHERE terms_type IN ('NON_FACE_TO_FACE_STORAGE', 'SUBSCRIPTION_SERVICE_TERMS')
ORDER BY version_number;
